-- TPC-H Q14 (sf100), generated by qgen -d -s 100
-- tpch-dbgen commit 32f1c1b92d1664dba542e927d23d86ffa57aa253
-- normalized: dropped 'where rownum <= -1' (no row limit)
select
	100.00 * sum(case
		when p_type like 'PROMO%'
			then l_extendedprice * (1 - l_discount)
		else 0
	end) / sum(l_extendedprice * (1 - l_discount)) as promo_revenue
from
	lineitem,
	part
where
	l_partkey = p_partkey
	and l_shipdate >= date '1995-09-01'
	and l_shipdate < date '1995-09-01' + interval '1' month;
